219	              << ";old_addr=" << std::hex << old_addr
220	              << ";new_addr=" << new_addr << std::dec;
221	            writeNode(ptag, "inj", dyn_seq, true, 0, false,
222	                      old_addr, true, 0, false, 0, false, d.str());
223	        }
