247	    CHAOSPropagation::registerCacheFault(Addr block_addr, int byte_offset,
248	                                         Addr block_size, const char *field)
249	    {
250	        if (!write_log)
251	            return 0;
252	        const uint64_t ptag = ++next_ptag;
253	
254	        // inj node (addr column = the faulted block address).
255	        {
256	            std::ostringstream d;
257	            d << "family=cache;field=" << field
258	              << ";byte_offset=" << byte_offset
259	              << ";block_addr=" << std::hex << block_addr << std::dec;
260	            writeNode(ptag, "inj", 0, false, 0, false,
261	                      block_addr, true, 0, false, 0, false, d.str());
262	        }
263	        if (byte_offset >= 0) {
264	            // Single faulted byte (data faults).
265	            sweepExpired();
266	            BlkEntry e;
267	            e.ptag = ptag;
268	            e.byte_begin = block_addr + (Addr)byte_offset;
269	            e.byte_end = e.byte_begin + 1;
270	            e.registered = curTick();
271	            blk_registry[e.byte_begin] = e;
272	        } else if (byte_offset == -1) {
273	            // Whole-block fault (data_shift rotate corrupts every byte).
274	            sweepExpired();
275	            BlkEntry e;
276	            e.ptag = ptag;
277	            e.byte_begin = block_addr;
278	            e.byte_end = block_addr + block_size;
279	            e.registered = curTick();
280	            blk_registry[block_addr] = e;
281	        }
282	        // byte_offset == -2 (metadata field / victim path): NO registry —
283	        // the chain honestly stops at the inj node (see .hh).
284	        return ptag;
