303	    void
304	    CHAOSPropagation::noteMemRequest(const char *site, uint64_t dyn_seq,
305	                                     const RequestPtr &req)
306	    {
307	        if (!write_log || !req || !req->hasVaddr())
308	            return;
309	        sweepExpired();
310	        const Addr v = req->getVaddr();
311	        const Addr v_end = v + (Addr)req->getSize();
312	
313	        // addrpath registry: range overlap + dyn-inst binding. The request
314	        // seq must be stamped (getReqInstSeqNum asserts otherwise — gem5
315	        // v25 request.hh); an unstamped request falls back to overlap-only
316	        // (documented: split _mainReq is not seq-stamped).
317	        const bool stamped = req->hasInstSeqNum();
318	        const uint64_t req_seq = stamped ? req->getReqInstSeqNum() : 0;
319	        for (const auto &kv : addr_registry) {
320	            const AddrEntry &e = kv.second;
321	            if (e.size == 0)
322	                continue;                       // address-only marker
323	            const Addr e_end = e.base + e.size;
324	            if (v >= e_end || e.base >= v_end)
325	                continue;                       // no overlap
326	            if (stamped && req_seq != e.dyn_seq)
327	                continue;                       // not the faulting inst
328	            std::ostringstream d;
329	            d << "site=" << site << ";family=addrpath;size="
330	              << req->getSize();
331	            writeNode(e.ptag, "mem_req", dyn_seq, true,
332	                      req_seq, stamped, v, true, 0, false, 0, false, d.str());
333	        }
334	
335	        // cache faulted-byte registry: range overlap (SE vaddr==paddr).
336	        for (const auto &kv : blk_registry) {
337	            const BlkEntry &e = kv.second;
338	            if (v >= e.byte_end || e.byte_begin >= v_end)
339	                continue;
340	            std::ostringstream d;
341	            d << "site=" << site << ";family=cache;size=" << req->getSize();
342	            writeNode(e.ptag, "mem_req", dyn_seq, true,
343	                      req_seq, stamped, v, true, 0, false, 0, false, d.str());
344	        }
345	    }
