352	            return;
353	        sweepExpired();
354	
355	        uint64_t hit_ptag = 0;
356	        const char *hit_family = nullptr;
357	
358	        // addrpath: the response's own Request vaddr range vs the registry,
359	        // bound to this instruction (the faulting load itself).
360	        if (pkt->req && pkt->req->hasVaddr()) {
361	            const Addr v = pkt->req->getVaddr();
362	            const Addr v_end = v + (Addr)pkt->req->getSize();
363	            for (const auto &kv : addr_registry) {
364	                const AddrEntry &e = kv.second;
365	                if (e.size == 0)
366	                    continue;
367	                if (v < e.base + e.size && e.base < v_end
368	                        && e.dyn_seq == inst->seqNum) {
369	                    hit_ptag = e.ptag;
370	                    hit_family = "addrpath";
371	                    break;
372	                }
373	            }
374	        }
375	        // cache: the delivered byte range vs the faulted-byte registry.
376	        if (!hit_ptag) {
377	            const Addr a = pkt->getAddr();
378	            const Addr a_end = a + (Addr)pkt->getSize();
379	            for (const auto &kv : blk_registry) {
380	                const BlkEntry &e = kv.second;
381	                if (a < e.byte_end && e.byte_begin < a_end) {
382	                    hit_ptag = e.ptag;
383	                    hit_family = "cache";
384	                    break;
385	                }
386	            }
387	        }
388	        if (!hit_ptag)
389	            return;
390	
391	        // resp node: the memory response delivering the fault.
392	        const uint64_t req_seq =
393	            (pkt->req && pkt->req->hasInstSeqNum())
394	                ? pkt->req->getReqInstSeqNum() : 0;
395	        {
396	            std::ostringstream d;
397	            d << "family=" << hit_family << ";size=" << pkt->getSize();
398	            if (pkt->hasData()) {
