437	    CHAOSPropagation::noteCommit(ThreadID tid, o3::DynInst *head_inst)
438	    {
439	        if (!write_log || !head_inst)
440	            return;
441	
442	        const uint64_t pc = head_inst->pcState().instAddr();
443	        uint64_t first_consumed_ptag = 0;
444	        bool any_consumer = false;
445	        bool self_taint = false;
446	        uint64_t self_taint_ptag = 0;
447	
448	        // Sources: a tainted source phys reg = this commit consumes a
449	        // fault-delivered value → consumer node.
450	        const int nsrc = (int)head_inst->numSrcRegs();
451	        for (int i = 0; i < nsrc; ++i) {
452	            const PhysRegIdPtr phys = head_inst->renamedSrcIdx(i);
453	            if (!phys)
454	                continue;
455	            const auto it = taint_set.find(
456	                std::make_pair(phys->classValue(), phys->index()));
457	            if (it == taint_set.end())
458	                continue;
459	            any_consumer = true;
460	            if (!first_consumed_ptag)
461	                first_consumed_ptag = it->second.ptag;
