464	              << ";src_idx=" << i << ";pc=" << std::hex << pc << std::dec;
465	            writeNode(it->second.ptag, "consumer", head_inst->seqNum, true,
466	                      0, false, 0, false, phys->index(), true,
467	                      head_inst->srcRegIdx(i).index(), true, d.str());
468	        }
469	
470	        // Dests: is this the faulting load itself committing its tainted
471	        // dest (taintor_seq == own seqNum)? That commit is the first
472	        // architectural materialization of the fault.
473	        const int ndest = (int)head_inst->numDestRegs();
474	        for (int i = 0; i < ndest; ++i) {
475	            const PhysRegIdPtr phys = head_inst->renamedDestIdx(i);
476	            if (!phys)
477	                continue;
478	            const auto it = taint_set.find(
479	                std::make_pair(phys->classValue(), phys->index()));
480	            if (it != taint_set.end()
481	                    && it->second.taintor_seq == head_inst->seqNum) {
482	                self_taint = true;
483	                if (!self_taint_ptag)
