498	                                             : "faulting_load_commit")
499	              << ";pc=" << std::hex << pc << std::dec;
500	            writeNode(ptag, "errant_commit", head_inst->seqNum, true,
501	                      0, false, 0, false, 0, false, 0, false, d.str());
502	            errant_commit_seen = true;
503	        }
504	
505	        // Propagation rules (see .hh):
506	        //  - consumer commits → its dests now carry the wrong value
507	        //    (re-taint under the consumed chain's ptag);
508	        //  - the tainting load's own commit → keep its dest taint;
509	        //  - an UNRELATED producer committing onto a tainted phys cell →
510	        //    clean overwrite, the stale taint dies (phys-recycling bound).
511	        if (any_consumer) {
512	            for (int i = 0; i < ndest; ++i) {
513	                const PhysRegIdPtr phys = head_inst->renamedDestIdx(i);
514	                if (!phys)
515	                    continue;
516	                TaintEntry te;
517	                te.ptag = first_consumed_ptag;
518	                te.taintor_seq = head_inst->seqNum;
