520	                                         phys->index())] = te;
521	            }
522	        } else if (!self_taint) {
523	            for (int i = 0; i < ndest; ++i) {
524	                const PhysRegIdPtr phys = head_inst->renamedDestIdx(i);
525	                if (!phys)
526	                    continue;
527	                taint_set.erase(std::make_pair(phys->classValue(),
528	                                               phys->index()));
529	            }
