Fault
LSQ::pushRequest(const DynInstPtr& inst, bool isLoad, uint8_t *data,
        unsigned int size, Addr addr, Request::Flags flags, uint64_t *res,
        AtomicOpFunctorPtr amo_op, const std::vector<bool>& byte_enable)
{
    // This comming request can be either load, store or atomic.
    // Atomic request has a corresponding pointer to its atomic memory
    // operation
    [[maybe_unused]] bool isAtomic = !isLoad && amo_op;

    // LSU W4 A-series PRE hook (W1 ⑦ ruling): pushRequest entry = the AGU's
    // raw output, the single mandatory pass-through point BEFORE split
    // decision and Request construction. Mutates the by-value addr/size
    // copies so every downstream consumer sees the fault. byte_enable is a
    // const ref here — BE mutation is NOT offered at this hook (A06 does
    // size only; documented in 09 §3-W4).
    if (cpu->chaosAddrPathPre) {
        const Addr pre_old_addr = addr;
        const unsigned int pre_old_size = size;
        size = cpu->chaosAddrPathPre->maybeCorruptPre(addr, size, isLoad,
                                                      flags);
        // [LSU][OBS-L3] register the PRE-family injection with the L3
        // propagation tracer (inj + addr_form nodes + addr registry).
        // lastPreHookInjected() also covers the flag-only modes (S06/L02
        // leave addr/size untouched — a before/after compare here would
        // miss them); their chain honestly stops at addr_form (no faulted
        // address to track). nullptr tracer / no injection = no-op.
        if (cpu->chaosPropagation &&
            cpu->chaosAddrPathPre->lastPreHookInjected()) {
            cpu->chaosPropagation->registerInjection(
                "lsq_pushRequest_PRE", inst->seqNum, pre_old_addr, addr,
                isLoad, pre_old_size, size);
        }
    }

    ThreadID tid = cpu->contextToThread(inst->contextId());
    auto cacheLineSize = cpu->cacheLineSize();
    bool needs_burst = transferNeedsBurst(addr, size, cacheLineSize);
    LSQRequest* request = nullptr;

    // Atomic requests that access data across cache line boundary are
    // currently not allowed since the cache does not guarantee corresponding
    // atomic memory operations to be executed atomically across a cache line.
    // For ISAs such as x86 that supports cross-cache-line atomic instructions,
    // the cache needs to be modified to perform atomic update to both cache
    // lines. For now, such cross-line update is not supported.
    assert(!isAtomic || (isAtomic && !needs_burst));

    const bool htm_cmd = isLoad && (flags & Request::HTM_CMD);
    const bool tlbi_cmd = isLoad && (flags & Request::TLBI_CMD);

    if (inst->translationStarted()) {
        request = inst->savedRequest;
        assert(request);

